function mergeStepsToSort(nums: number[]): number {
  const a = [...nums];
  const sorted = () => a.every((v, i) => i === 0 || a[i - 1] <= v);
  let steps = 0;
  while (!sorted()) {
    let best = 0;
    for (let i = 1; i + 1 < a.length; i++) {
      if (a[i] + a[i + 1] < a[best] + a[best + 1]) best = i; // strict: leftmost wins ties
    }
    a.splice(best, 2, a[best] + a[best + 1]);
    steps++;
  }
  return steps;
}

