class MinHeap {
  private h: [number, number][] = [];
  get size() { return this.h.length; }
  private less(x: [number, number], y: [number, number]) { return x[0] < y[0] || (x[0] === y[0] && x[1] < y[1]); }
  push(v: [number, number]) {
    const h = this.h; h.push(v);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.less(h[i], h[p])) break;
      [h[i], h[p]] = [h[p], h[i]]; i = p;
    }
  }
  pop(): [number, number] {
    const h = this.h, top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && this.less(h[l], h[m])) m = l;
        if (r < h.length && this.less(h[r], h[m])) m = r;
        if (m === i) break;
        [h[i], h[m]] = [h[m], h[i]]; i = m;
      }
    }
    return top;
  }
}

function mergeStepsToSort(nums: number[]): number {
  const n = nums.length;
  const val = [...nums];
  const prev = val.map((_, i) => i - 1);
  const next = val.map((_, i) => i + 1); // n means "no next"
  const alive = new Array(n).fill(true);
  let descents = 0;
  const heap = new MinHeap();
  for (let i = 0; i + 1 < n; i++) {
    if (val[i] > val[i + 1]) descents++;
    heap.push([val[i] + val[i + 1], i]);
  }
  let steps = 0;
  while (descents > 0) {
    const [s, i] = heap.pop();
    const j = next[i];
    if (!alive[i] || j >= n || val[i] + val[j] !== s) continue; // stale entry
    const k = prev[i], l = next[j];
    if (k >= 0 && val[k] > val[i]) descents--;
    if (val[i] > val[j]) descents--;
    if (l < n && val[j] > val[l]) descents--;
    val[i] += val[j];
    alive[j] = false;
    next[i] = l;
    if (l < n) prev[l] = i;
    if (k >= 0 && val[k] > val[i]) descents++;
    if (l < n && val[i] > val[l]) descents++;
    if (k >= 0) heap.push([val[k] + val[i], k]);
    if (l < n) heap.push([val[i] + val[l], i]);
    steps++;
  }
  return steps;
}

