class Solution:
    def mergeStepsToSort(self, nums: List[int]) -> int:
        n = len(nums)
        val = list(nums)
        prev = [i - 1 for i in range(n)]
        nxt = [i + 1 for i in range(n)]  # n means "no next"
        alive = [True] * n
        descents = 0
        heap = []
        for i in range(n - 1):
            if val[i] > val[i + 1]:
                descents += 1
            heap.append((val[i] + val[i + 1], i))
        heapq.heapify(heap)
        steps = 0
        while descents > 0:
            s, i = heapq.heappop(heap)
            j = nxt[i]
            if not alive[i] or j >= n or val[i] + val[j] != s:
                continue  # stale entry
            k, l = prev[i], nxt[j]
            if k >= 0 and val[k] > val[i]:
                descents -= 1
            if val[i] > val[j]:
                descents -= 1
            if l < n and val[j] > val[l]:
                descents -= 1
            val[i] += val[j]
            alive[j] = False
            nxt[i] = l
            if l < n:
                prev[l] = i
            if k >= 0 and val[k] > val[i]:
                descents += 1
            if l < n and val[i] > val[l]:
                descents += 1
            if k >= 0:
                heapq.heappush(heap, (val[k] + val[i], k))
            if l < n:
                heapq.heappush(heap, (val[i] + val[l], i))
            steps += 1
        return steps

